# Add cover URLs (using Google Books cover API format)
for genre_id, books in books_by_genre.items():
    for book in books:
        book["genre"] = genre_id
        book["coverUrl"] = f"https://books.google.com/books/content?id={book['id']}&printsec=frontcover&img=1&zoom=1&source=gbs_api"
        if "externalUrl" not in book:
            book["externalUrl"] = f"https://www.google.com/search?tbm=bks&q={book['title'].replace(' ', '+')}+{book['author'].split()[0]}"

# Save
with open("books_cache.json", "w", encoding="utf-8") as f:
    json.dump(books_by_genre, f, indent=2, ensure_ascii=False)

total = sum(len(v) for v in books_by_genre.values())
print(f"Generated {total} books across {len(books_by_genre)} genres")
for gid, books in books_by_genre.items():
    print(f"  {gid}: {len(books)} books")
